{
  "justification": "Salience is concentrated on health, education, and care for the elderly, and the electorate leans left economically (mean 2.39) with 71% preferring higher taxes and services, pointing to strong Care and Equality priorities. While these foundations can pull either toward expansive provision or caution about costs/risks, the balance of vote-deciding attention (EU, law-and-order small) indicates only secondary activation of Loyalty/Authority and minimal Sanctity, with Proportionality mainly via tax/economic concerns among a minority.",
  "foundations": [
    {"foundation": "care", "basis": "High salience of health (33.6%), education (25.6%), and pensions/elderly care (4.3%).", "weight": 0.4},
    {"foundation": "equality", "basis": "Left-right mean 2.39 and 71.3% favor increasing taxes and social services; equality/social justice salience 0.8%.", "weight": 0.25},
    {"foundation": "proportionality", "basis": "Tax-versus-services split (28.7% for lower taxes/services), macro-economic issues 7.9%, tax salience 3.2%.", "weight": 0.13},
    {"foundation": "loyalty", "basis": "EU salience 8.6% plus small defence (0.2%) and immigration/refugees (0.2%).", "weight": 0.1},
    {"foundation": "authority", "basis": "Law+order/crime/policing/sentencing/prisons 3.6% and small family values (0.2%).", "weight": 0.08},
    {"foundation": "sanctity", "basis": "Low salience of purity-adjacent issues: environment 1.0% and family values 0.2%.", "weight": 0.04}
  ]
}
